(async()=>{const out={};for(const kind of ['set','linear','detune']){const c=new OfflineAudioContext(1,384,8000),s=c.createBufferSource(),b=c.createBuffer(1,512,8000);b.getChannelData(0).set(Array.from({length:512},(_,i)=>i%17));s.buffer=b;s.connect(c.destination);if(kind==='set')s.playbackRate.setValueAtTime(2,128/8000);if(kind==='linear')s.playbackRate.linearRampToValueAtTime(2,256/8000);if(kind==='detune')s.detune.setValueAtTime(1200,128/8000);s.start();out[kind]=Array.from((await c.startRendering()).getChannelData(0))}return out})()
